24	import org.springframework.validation.Errors;
25	import org.springframework.validation.ValidationUtils;
26	import org.springframework.validation.Validator;
27	
28	/**
29	 * Rejects an {@link OwnerFieldsDto} whose required identity fields are missing or blank
30	 * (null, empty or whitespace-only). This complements the schema's bean-validation
31	 * constraints, which do not treat a whitespace-only address or city as invalid.
32	 */
33	public class OwnerFieldsValidator implements Validator {
34	
35	    private static final List<String> REQUIRED_FIELDS =
36	        List.of("firstName", "lastName", "address", "city", "telephone");
37	
38	    @Override
39	    public boolean supports(Class<?> clazz) {
40	        return OwnerFieldsDto.class.isAssignableFrom(clazz);
41	    }
42	
43	    @Override
44	    public void validate(Object target, Errors errors) {
45	        OwnerFieldsDto owner = (OwnerFieldsDto) target;
46	        owner.setAddress(AddressNormalizer.normalize(owner.getAddress()));
47	        for (String field : REQUIRED_FIELDS) {
48	            ValidationUtils.rejectIfEmptyOrWhitespace(errors, field, "required", "must not be blank");
49	        }
50	        String telephone = owner.getTelephone();
51	        String raw = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
52	        String e164 = raw.startsWith("+") ? raw
53	            : "+61" + (raw.startsWith("0") ? raw.substring(1) : raw);
54	        if (E164Telephone.isValid(e164)) {
55	            owner.setTelephone(e164);
56	        } else {
57	            errors.rejectValue("telephone", "telephone", "must be a valid E.164 telephone number");
58	        }
