        if (email == null) {
            return;
        }
        int at = email.lastIndexOf('@');
        String domain = at < 0 ? "" : email.substring(at + 1).toLowerCase(Locale.ROOT);
        if (BLOCKED.contains(domain)) {
            errors.rejectValue("email", "email", "must not use a disposable-email domain");
        }
    }
}

